import type { BChap } from '../types';
const C: BChap[] = [{"v":["Початок Євангелія Ісуса Христа, Сина Божого.","Як написано у пророків: ось Я посилаю ангела Мого перед лицем Твоїм, який приготує путь Твою перед Тобою.","Глас вопіющого в пустелі: приготуйте путь Господеві, прямими зробіть стезі Йому.","Явився Іоан, який хрестив у пустелі і проповідував хрещення на покаяння для відпущення гріхів.","І виходили до нього з усієї країни Юдейської і єрусалимляни; і всі хрестилися в річці Йордані від нього, сповідаючи гріхи свої.","Іоан же носив одяг з верблюжого волоса і пояс шкіряний на стегнах своїх і їв акриди* та дикий мед.","І проповідував, кажучи: гряде Сильніший за мене слідом за мною, Якому я недостойний, нахилившись, розв’язати ремінь взуття Його.","Я хрестив вас водою, а Він хреститиме вас Духом Святим.","І сталось у ті дні, прийшов Ісус із Назарета галилейського і хрестився від Іоана в Йордані.","І коли виходив з води, зараз же побачив Іоан небеса, що розкривалися, і Духа, Який, мов голуб, сходив на Нього.","І голос був з небес: Ти Син Мій Улюблений, в Якому Моє благовоління.","Негайно після того Дух веде Його в пустелю.","І пробув Він там у пустелі сорок днів, спокушуваний сатаною, і був із звірами; і ангели служили Йому.","Після того ж, як виданий був Іоан, прийшов Ісус до Галилеї, проповідуючи Євангеліє Царства Божого","і кажучи, що настав час і наблизилося Царство Боже: покайтеся і віруйте в Євангеліє.","Проходячи ж біля моря Галилейського, побачив Симона і Андрія, брата Симонового, що закидали неводи в море, бо вони були рибалками.","І сказав їм Ісус: ідіть за Мною, і Я зроблю, що ви будете ловцями людей.","І вони відразу ж, покинувши свої сіті, пішли за Ним.","І, пройшовши звідтіля трохи, Він побачив Якова Зеведеєвого і Іоана, брата його, які також були у човні, лагодили сіті;","і зараз же покликав їх. І вони, залишивши батька свого Зеведея в човні з наймитами, пішли за Ним.","І приходять до Капернаума; і незабаром у суботу увійшов Він у синагогу і навчав.","І дивувалися вченню Його; бо Він учив їх, як Такий, що має владу, а не як книжники.","І був у синагозі їхній чоловік, який мав у собі духа нечистого, і закричав:","облиш, що Тобі до нас, Ісусе Назарянине? Ти прийшов погубити нас! Знаю Тебе, хто Ти, — Святий Божий.","І заборонив йому Ісус, кажучи: замовкни і вийди з нього.","І стряс його дух нечистий і, скрикнувши гучним голосом, вийшов з нього.","І вжахнулися всі так, що один одного питали: що це, що це за нове вчення, що Він владно і духам нечистим наказує, і вони слухаються Його?","І враз розійшлися про Нього чутки по всій країні Галилейській.","Вийшовши невдовзі з синагоги, прийшли до господи Симона і Андрія, з Яковом та Іоаном.","Теща ж Симонова лежала в гарячці; і зразу сказали Йому про неї.","І, підійшовши, Він підняв її, взявши її за руку; і гарячка зараз же залишила її, і вона почала слугувати їм.","Надвечір, коли заходило сонце, приносили до Нього всіх недужих і біснуватих.","І все місто зібралося біля дверей.","І Він зцілив багатьох, що страждали всякими недугами; вигнав багатьох бісів, і не дозволяв бісам говорити, що вони знають, що Він Христос.","А вранці, ще затемна, вставши, вийшов і пішов у безлюдне місце і там молився.","І поспішили за Ним Симон і ті, що були з Ним,","і, знайшовши Його, кажуть Йому: всі Тебе шукають.","Він говорить їм: ходімо в найближчі села та міста, щоб Мені і там проповідувати; бо Я для того прийшов.","І Він проповідував у синагогах їхніх по всій Галилеї і виганяв бісів.","Приходить до Нього прокажений і, благаючи Його та падаючи перед Ним на коліна, говорить Йому: якщо хочеш, можеш мене очистити.","Ісус, змилосердившись над ним, простягнув руку, доторкнувся до нього і сказав йому: хочу, очисться.","І як тільки сказав, зараз же зійшла з нього проказа, і він став чистим.","І, заборонивши йому, негайно відіслав його.","І сказав йому: гляди ж, нікому нічого не кажи, але піди покажись священикові і принеси за очищення твоє, що повелів Мойсей, — на свідчення їм.","А він, вийшовши, почав розголошувати і розповідати про подію, яка сталася, так що Ісус не міг уже явно ввійти до міста, але перебував зовні, в безлюдних місцях. І приходили до Нього звідусіль."],"x":{"2":"49.3.1|50.11.10|52.7.27","3":"31.40.3|50.3.3|52.3.4|53.1.23","4":"50.3.1|52.3.3|53.1.31|54.13.24","6":"2.11.22|50.3.4","7":"52.3.16|53.1.27","8":"54.1.5|54.2.4|63.12.13","9":"50.3.13|52.3.21","10":"50.3.16|52.3.21|53.1.32","12":"50.4.1|52.4.1","14":"50.4.12|52.4.14|53.4.43","15":"50.4.17","16":"50.4.18","21":"50.4.13|52.4.31","22":"50.7.28|52.4.32","23":"52.4.33","24":"37.9.24|50.8.29|55.2.19","29":"50.8.14|52.4.38","32":"50.8.16|52.4.40","34":"51.3.12|52.4.41|54.16.17|54.19.15","38":"52.4.43","40":"50.8.2|52.5.12","44":"2.13.2|50.8.4|52.5.14"},"n":{"6":["Акриди — вид сарани."]}},{"v":["Коли через кілька днів знову прийшов до Капернаума, пішла чутка, що Він у домі.","Зразу ж зібралося багато людей, так що вже не вміщалися біля дверей, і Він говорив їм слово.","І прийшли до Нього з розслабленим, якого несли четверо.","І, не маючи можливости наблизитись до Нього через народ, розкрили покрівлю дому, де Він був, і, розібравши її, спустили постіль, на якій лежав розслаблений.","Ісус, побачивши віру їхню, говорить розслабленому: чадо, відпускаються тобі гріхи твої.","Були там деякі з книжників, що сиділи і помишляли в серцях своїх:","чому Цей так богохулить? Хто може прощати гріхи, крім одного Бога?","Ісус, відразу зрозумівши духом Своїм, що вони так помишляють у собі, сказав їм: навіщо так помишляєте в серцях ваших?","Що легше — сказати розслабленому: прощаються тобі гріхи? Чи сказати: встань, візьми постіль свою і ходи?","Та щоб ви знали, що Син Людський має владу на землі відпускати гріхи, — говорить розслабленому:","тобі кажу: встань, візьми постіль твою та йди до дому твого.","Він зараз же встав і, взявши постіль, вийшов перед усіма, так що всі дивувались і прославляли Бога, кажучи: ніколи ще такого ми не бачили.","І вийшов Ісус знову до моря; і весь народ пішов до Нього, і учив їх.","Проходячи, побачив Він Левія Алфеєвого, що сидів на митниці, і сказав йому: йди за Мною. І той, вставши, пішов за Ним.","І коли Ісус возлежав у господі його, возлежали з Ним і ученики Його і багато митарів та грішників; бо багато їх було, і вони йшли за Ним.","Книжники й фарисеї, побачивши, що Він їсть з митарями і грішниками, говорили ученикам Його: як це Він їсть і п’є з митарями і грішниками?","Почувши це, Ісус говорить їм: не здорові потребують лікаря, але хворі; Я прийшов покликати не праведників, а грішників до покаяння.","Учні Іоанові та фарисейські постили. Приходять до Нього і кажуть: чому учні Іоанові та фарисейські постять, а Твої ученики не постять?","І сказав їм Ісус: чи можуть постити гості весільні, коли з ними жених? Доки з ними жених, не можуть постити.","Прийдуть же дні, коли заберуть від них жениха, і тоді поститимуть у ті дні.","І ніхто не пришиває латки з нової тканини до старої одежі: інакше нове відірветься від старого, і ще гірша дірка буде.","І ніхто не вливає вина молодого в міхи старі: інакше молоде вино прорве міхи, і вино витече, і міхи пропадуть; але вино молоде треба вливати в міхи нові.","І довелося Йому в суботу проходити через посіви, і ученики Його дорогою почали рвати колоски.","І фарисеї сказали Йому: дивись, що вони роблять у суботу, чого не слід робити.","Він сказав їм: невже ви ніколи не читали, що зробив Давид, коли мав потребу, бо зголоднів сам і ті, що були з ним?","Як увійшов він у дім Божий за первосвященика Авиафара і їв хліби принесення, яких не повинен їсти ніхто, крім священиків, і дав тим, що були з ним?","І сказав їм: субота для людини, а не людина для суботи;","тому Син Людський є господар і суботи."],"x":{"1":"50.9.1","3":"50.9.2|52.5.18","5":"31.43.25","8":"53.2.24|53.6.64","9":"50.9.5|52.5.23","14":"50.9.9|52.5.27","17":"50.9.13|52.5.32|71.1.15","18":"50.9.14|52.5.33","21":"50.9.16|52.5.36","23":"4.23.25|50.12.1|52.6.1","26":"1.29.33|2.24.9|8.21.6|50.12.4|52.6.4"}},{"v":["І знов увійшов до синагоги. І там був чоловік, який мав усохлу руку.","І стежили за Ним, чи не зцілить його в суботу, щоб звинуватити Його.","Він же говорить чоловікові, котрий мав усохлу руку: стань посередині.","А їм говорить: чи годиться в суботу добро робити, чи зло робити — душу спасти чи загубити? Вони ж мовчали.","І, глянувши на них з гнівом, засмучений закам’янілістю сердець їхніх, каже чоловікові: простягни руку твою. Він простягнув, і стала рука його здорова, як друга.","Фарисеї, вийшовши, зразу ж радилися з іродіанами проти Нього, як би погубити Його.","Але Ісус з учениками Своїми відійшов до моря; і за Ним пішло багато народу з Галилеї, Юдеї,","з Єрусалима, Ідумеї, з-за Йордану; та з Тира й Сидона, почувши, що Він робив, йшли до Нього у великій кількості.","І сказав ученикам Своїм, щоб приготували для Нього човен, через багатолюдність, аби не тіснилися до Нього.","Бо багатьох Він зцілив, тому ті, які мали рани, кидалися до Нього, щоб торкнутися Його.","І духи нечисті, коли бачили Його, падали перед Ним і кричали: Ти Син Божий.","Та Він суворо забороняв їм, щоб не робили Його відомим.","Потім зійшов на гору і покликав до Себе, кого Сам хотів; і прийшли до Нього.","І обрав з них дванадцять, щоб були з Ним і щоб посилати їх на проповідь,","і щоб вони мали владу зціляти від недуг і виганяти бісів.","І поставив Симона, давши йому ім’я Петро,","Якова Зеведеєвого та Іоана, брата Якова, давши їм імення Воанергес, тобто «сини громові»,","Андрія, Филипа, Варфоломія, Матфея, Фому, Якова Алфеєвого, Фадея, Симона Кананіта","та Іуду Іскаріотського, який і зрадив Його.","Приходять у дім; і знову збирається народ, так що їм неможливо було і хліба їсти.","І, почувши, ті, хто був у Нього, пішли взяти Його, бо говорили, що Він не при собі.","А книжники, які прийшли з Єрусалима, говорили, що Він має в Собі Вельзевула і що силою бісівського князя виганяє бісів.","І, покликавши їх, говорив їм притчами: як може сатана виганяти сатану?","Якщо царство розділиться само в собі, не може встояти царство те.","І якщо дім розділиться сам у собі, не може встояти дім той.","І якщо сатана повстав сам на себе і розділився, не може встояти, але прийшов кінець його.","Ніхто, ввійшовши в дім сильного, не може пограбувати речей його, якщо раніш не зв’яже сильного, і тоді розграбує дім його.","Істинно кажу вам: простяться синам людським усі гріхи та хули, якими б вони не хулили;","хто ж хулитиме Духа Святого, тому не буде прощення довіку, але підлягає він вічному осуду.","Бо ж говорили: в Ньому нечистий дух.","Прийшли Мати і брати Його і, стоячи надворі, послали до Нього покликати Його.","Навколо Нього сидів народ. І сказали Йому: ось Мати Твоя і брати Твої і сестри Твої надворі, шукають Тебе.","І відповів їм: хто мати Моя і брати Мої?","І, поглянувши довкола Себе на тих, що сиділи, сказав: ось мати Моя і брати Мої;","бо хто творитиме волю Божу, той брат Мій, і сестра Моя, і мати Моя."],"x":{"1":"50.12.9|52.6.6","6":"53.10.39","7":"50.4.25","11":"50.16.16","14":"50.10.1|52.9.1","16":"50.16.18","21":"53.10.20","22":"50.9.34|52.11.15","24":"50.12.25|52.11.17","28":"50.12.31|52.12.10|58.5.16|75.10.26","31":"50.12.46|52.8.19"}},{"v":["І знову почав навчати біля моря; і зібралося до Нього багато народу, так що Він увійшов у човен і сидів на морі; а весь народ був біля моря на землі.","І багато вчив їх притчами, і в навчанні Своєму говорив їм:","слухайте, ось вийшов сівач сіяти;","і, коли сіяв, трапилося, що одне зерно впало при дорозі, і налетіли птахи і видзьобали його.","Інше ж упало на кам’янисте місце, де небагато було землі; і скоро зійшло, бо земля була неглибока.","Коли ж зійшло сонце, зів’яло і, не маючи коріння, засохло.","Ще інше впало в терня; і виросло терня, і заглушило зерно, і воно не дало плоду.","А інше впало на добру землю і дало плід, який зійшов і виріс; і вродило в тридцять, в шістдесят і в стократ.","І сказав їм: хто має вуха слухати, нехай слухає!","Коли ж залишився на самоті, то ті, що були з Ним разом з дванадцятьма, запитали Його про притчу.","І сказав їм: вам дано знати тайни Царства Божого, а тим, зовнішнім, усе буває в притчах,","так що вони своїми очима дивляться, і не бачать; своїми вухами чують, і не розуміють, та й не навернуться, щоб відпустились їм гріхи.","І говорить їм: не розумієте цієї притчі? Як же вам зрозуміти всі притчі?","Сівач слово сіє.","Посіяне при дорозі означає тих, у яких сіється слово, але, як тільки почують слово, зараз же приходить сатана і забирає слово, посіяне в серцях їхніх.","Так само і посіяне на камені означає тих, які, коли почують слово, зразу з радістю сприймають його,","але не мають у собі кореня і непостійні; а потім, коли настане скорбота або гоніння за слово, відразу спокушаються.","Посіяне між терням означає тих, що слухають слово,","але в яких турботи віку цього, спокуси багатством та інші пожадання, увійшовши в них, заглушують слово, і воно безплідним буває.","А посіяне на добрій землі означає тих, що слухають слово і приймають, і приносять плід один у тридцять, другий в шістдесят, інший в стократ.","І сказав їм: чи для того приносять світильник, щоб поставити під посудину або під ліжко? Чи не для того, щоб поставити на свічнику?","Нема нічого таємного, що не стало б явним, і нічого не буває захованого, що не виявилося б.","Коли хто має вуха слухати, нехай слухає!","І сказав їм: дотримуйтесь того, що чуєте: якою мірою міряєте, такою відмірено буде вам, тим, що слухають.","Бо хто має, тому дасться; а хто не має, у того відніметься і те, що має.","І сказав: Царство Боже подібне до того, як коли чоловік кине насіння в землю;","і чи спить, чи встає вночі та вдень, а насіння сходить і росте, а як — не знає він.","Земля бо сама з себе родить спочатку стебло, потім колос, далі повне зерно в колосі.","Коли ж достигне плід, негайно посилає серп, бо настали жнива.","І сказав: до чого уподібнимо Царство Боже? Або якою притчею зобразимо його?","Воно — мов зерно гірчичне, яке, коли сіється в землю, дрібніше за всяке насіння на землі.","А коли посіяне, сходить і стає більше від усякого зілля та дає таке велике гілля, що під тінню його можуть укриватися птахи небесні.","І такими багатьма притчами проповідував їм слово, скільки вони могли слухати.","Без притчі ж не говорив їм; а ученикам на самоті пояснював усе.","І сказав їм увечері того ж дня: переправимось на той бік.","І, відпустивши народ, узяли Його, як Він був у човні; і з Ним були інші човни.","І знялась велика буря; хвилі били в човен так, що він уже наповнювався водою.","А Він спав на кормі на підголівнику. Його розбудили і говорять Йому: Учителю, невже Тобі байдуже, що ми гинемо?","І, вставши, Він заборонив вітрові і сказав морю: умовкни, перестань. І стих вітер, і настала велика тиша.","І сказав їм: чого ви такі боязкі? Чому не маєте віри?","І страх великий напав на них, і говорили між собою: Хто ж Цей, що і вітер, і море слухають Його?"],"x":{"1":"50.13.1|52.8.4","11":"50.11.25|50.16.17|63.2.10","12":"31.6.9-10|50.13.14|52.8.10|53.12.40","14":"50.13.18|52.8.11","16":"31.42.20|36.33.31|53.5.35","19":"52.12.15|71.6.9","21":"50.5.15|52.8.16","22":"50.10.26|52.8.17|52.12.2","24":"50.7.2|52.6.38","25":"50.13.12|50.25.29|52.8.18|52.19.26","30":"50.13.31|52.13.18","33":"50.13.34","35":"50.8.23|52.8.22","39":"24.26.12|25.88.10"}},{"v":["І прийшли на другий берег моря, в країну Гадаринську.","І коли вийшов Він з човна, зразу зустрів Його чоловік, який вийшов з гробів і мав духа нечистого;","він жив у гробах, і ніхто не міг його зв’язати, навіть ланцюгами,","бо багато разів він був скований кайданами та ланцюгами, але розривав ланцюги і розбивав залізні кайдани, і ніхто не мав сили приборкати його.","Завжди, вночі та вдень, був він у гробах і в горах, кричав та бився об каміння.","Побачивши ж Ісуса здаля, прибіг і поклонився Йому.","І, скрикнувши гучним голосом, сказав: що Тобі до мене, Ісусе, Сину Бога Всевишнього? Заклинаю Тебе Богом, не муч мене!","Бо Ісус сказав йому: вийди, душе нечистий, з цього чоловіка.","І спитав його: як твоє ім’я? І він сказав у відповідь: легіон ім’я моє, бо багато нас.","І благав Його вельми, щоб не висилав їх геть з країни тієї.","Паслось же там біля гори велике стадо свиней.","І благали Його всі біси, кажучи: пошли нас у свиней, щоб нам увійти в них.","Ісус відразу повелів їм. І, вийшовши, духи нечисті увійшли в свиней; і кинулося стадо з кручі в море, а їх було близько двох тисяч; і потонули в морі.","Пастухи ж свиней побігли і розказали у місті і в селах. І жителі вийшли подивитись, що сталося.","Приходять до Ісуса і бачать, що біснуватий, в якому був легіон, сидить — і одягнений, і при здоровому розумі; і злякалися.","Очевидці ж розказали їм про те, як це сталося з біснуватим, і про свиней.","І почали благати Його, щоб відійшов від меж їхніх.","І коли Він увійшов у човен, колишній біснуватий просив Його, щоб бути з Ним.","Але Ісус не дозволив йому, а сказав: йди додому до своїх і розкажи їм, що створив з тобою Господь і як помилував тебе.","І пішов, і почав проповідувати у Десятиградді про те, що сотворив з ним Ісус; і всі дивувалися.","Коли Ісус знову переправився в човні на той бік, зібралося до Нього багато народу; Він був біля моря.","І ось приходить один з начальників синагоги на ім’я Іаїр і, побачивши Його, падає до ніг Його","і дуже благає Його, кажучи: дочка моя при смерті; прийди і поклади на неї руки, щоб вона видужала і залишилася жива.","Ісус пішов з ним. За Ним йшло багато народу, і тиснули на Нього.","Якась жінка, що хворіла на кровотечу дванадцять років,","багато потерпіла від багатьох лікарів, і витратила все, що було в неї, і не дістала ніякого полегшення, але їй стало ще гірше, —","почувши про Ісуса, підійшла ззаду в натовпі і доторкнулась до одягу Його,","бо говорила: якщо доторкнусь хоч до одежі Його, то видужаю.","І зразу припинилась у неї кровотеча; і вона відчула тілом, що зцілилася від недуги.","І негайно Ісус відчув у Собі, що вийшла з Нього сила, звернувся до народу і сказав: хто доторкнувся до одежі Моєї?","Ученики сказали Йому: Ти бачиш, що натовп тисне на Тебе, і говориш: хто доторкнувся до Мене?","Але Він оглядався навкруги, щоб бачити ту, яка зробила це.","Жінка ж, знаючи, що з нею сталося, зі страхом і трепетом підійшла, впала перед Ним і сказала Йому всю правду.","Він же сказав їй: дочко, віра твоя спасла тебе. Іди з миром і будь здорова від недуги твоєї.","Коли він ще говорив це, приходять від начальника синагоги і кажуть: дочка твоя померла; чого ще турбуєш Учителя?","Але Ісус, почувши ці слова, зразу говорить начальникові синагоги: не бійся, тільки віруй.","І не дозволив нікому йти за Собою, крім Петра, Якова та Іоана, брата Якова.","І прийшов у дім начальника синагоги і бачить тривогу і тих, що плакали та дуже голосили.","І, увійшовши, говорить їм: чого тривожитесь і плачете? Дівчина не вмерла, а спить.","І глузували з Нього. Він же, виславши всіх, бере з Собою батька й матір дівчини і тих, що були з Ним, і входить туди, де лежала дівчина.","І, взявши дівчину за руку, каже їй: «таліфа, кумі», що значить: дівчино, тобі кажу, встань.","В ту ж мить дівчина встала і почала ходити, бо була років дванадцяти. І всі, хто бачив, жахнулися від дива великого.","І Він суворо наказав їм, щоб ніхто про це не знав, і сказав: дайте їй їсти."],"x":{"1":"50.8.28|52.8.26","25":"50.9.20","30":"52.8.45","35":"52.8.49"}},{"v":["І вийшов звідти Він, і прийшов у Свою батьківщину, і за Ним ішли ученики Його.","Коли настала субота, Він почав навчати в синагозі; і багато з тих, хто слухав, дивуючись, говорили: звідки в Ньому це? Що за премудрість дана Йому, і що за сили в руках Його?","Хіба не тесля Він, син Марії, брат Якова, Іосії, Іуди і Симона? Чи не тут, між нами, Його сестри? І спокушалися через Нього.","Ісус же сказав їм: не буває пророка без пошани, хіба тільки на батьківщині своїй, і серед родичів, і в домі своїм.","І не міг створити там ніякого чуда, тільки зцілив небагатьох недужих, поклавши на них руки.","І дивувався невір’ю їхньому; і обходив села навколишні, і навчав.","І покликавши дванадцятьох, почав посилати їх по двоє, даючи їм владу над нечистими духами.","І заповідав їм нічого не брати в дорогу, тільки один жезл: ні торбини, ні хліба, ні міді в поясі,","щоб були взуті у сандалі і не зодягалися у дві одежі.","І сказав їм: коли де увійдете в дім, залишайтеся в ньому, доки не підете з того місця.","І коли хто не прийме вас і не послухає вас, виходячи звідти, обтрусіть порох з ніг ваших, на свідчення проти них. Істинно кажу вам: відрадніше буде Содому і Гоморрі в день судний, ніж місту тому.","Вони пішли і проповідували, щоб покаялися;","виганяли багатьох бісів і багатьох хворих мазали оливою і зціляли.","Цар Ірод, почувши про Ісуса [бо Його ім’я стало відомим], говорив: це Іоан Хреститель воскрес з мертвих, і тому чудеса діються ним.","Одні говорили, що це Ілля, а інші говорили, що то пророк або один з пророків.","Ірод же, почувши, сказав: це Іоан, якому я відсік голову; він воскрес з мертвих.","Бо цей Ірод, пославши, взяв Іоана і посадив його у в’язницю, через Іродіаду, жінку Филипа, брата свого, з якою він одружився.","Бо Іоан говорив Іродові: не годиться тобі мати жінку брата твого.","Іродіада ж, гніваючись на нього, бажала вбити його, та не могла.","Бо Ірод боявся Іоана, знаючи, що він муж праведний і святий, і охороняв його; багато що робив, слухаючись його, та із задоволенням слухав його.","І настав нагідний день, коли Ірод, святкуючи день свого народження, влаштував бенкет для вельмож своїх, тисяцьких і старійшин галилейських;","і увійшла дочка Іродіади, танцювала і догодила Іродові і тим, що возлежали з ним; цар сказав дівчині: проси в мене, чого хочеш, і дам тобі.","І клявся їй: чого тільки попросиш у мене, дам тобі, навіть до половини мого царства.","Вона вийшла і спитала у матері своєї: що просити? Та відповіла: голову Іоана Хрестителя.","Вона відразу ж пішла з поспішністю до царя і просила, кажучи: хочу, щоб ти зараз же дав мені на блюді голову Іоана Хрестителя.","Цар засмутився, але, заради клятви і тих, що возлежали з ним, не захотів відмовити їй.","І негайно, пославши ката, цар звелів принести голову його.","Той пішов, відсік йому голову в темниці, і приніс голову його на блюді, і віддав її дівчині, а дівчина віддала її матері своїй.","Учні його, почувши, прийшли і взяли тіло його, і поклали його у гробі.","І зібрались апостоли до Ісуса і розповіли Йому все, і що зробили, і чого навчили.","Він сказав їм: підіть ви одні у безлюдне місце і трохи відпочиньте, — бо так багато народу приходило і відходило, що їм ніколи було і їсти.","І вирушили в безлюдне місце в човні одні.","І побачили їх, як вони вирушали, і багато хто впізнав їх; і сходились туди піші з усіх міст, і випередили їх, і зійшлись до Нього.","Ісус, вийшовши, побачив багато людей і змилосердився над ними, бо вони були як вівці, що не мають пастиря; і почав навчати їх багато.","І вже минуло багато часу, коли ученики Його приступили до Нього, кажучи: місце тут людне, а час уже пізній, —","відпусти їх, щоб вони пішли у навколишні селища та села і купили собі хліба; бо їм нічого їсти.","Він сказав їм у відповідь: ви дайте їм їсти. І сказали Йому: чи ми маємо піти купити хліба динаріїв на двісті і дати їм їсти?","Але Він сказав їм: скільки у вас є хлібів? Підіть і подивіться. Вони, довідавшись, сказали: п’ять хлібів і дві рибини.","Тоді повелів їм розсадити всіх рядами на зеленій траві.","І посідали рядами, по сто і по п’ятдесят.","Він взяв п’ять хлібів і дві рибини, звівши очі на небо, благословив і розломив хліби і дав ученикам Своїм, щоб вони роздали їм; і обидві рибини поділив на всіх.","І всі їли, і наситились.","І набрали шматків хліба і залишків від риб дванадцять повних кошиків.","Було ж тих, що їли хліби, близько п’яти тисяч мужів.","І зразу наказав ученикам Своїм увійти в човен і переправитись раніше за Нього на той бік до Вифсаїди, поки Він відпустить народ.","І, відпустивши їх, пішов на гору помолитись.","Увечері човен був посеред моря, а Він один на землі.","І побачив, як вони знемагали у плаванні; бо вітер їм був зустрічний; близько до четвертої сторожі ночі прийшов до них, ідучи по морю, і хотів проминути їх.","Вони ж, побачивши, що Він іде по морю, подумали, що це привид, і закричали.","Бо всі побачили Його і стривожилися. І зараз же заговорив з ними і сказав їм: підбадьоріться! Це Я, не бійтеся!","І увійшов до них у човен; і вітер стих. І вони надзвичайно про себе жахалися і дивувалися,","бо не зрозуміли і чуда з хлібами, тому що серце їхнє було скам’яніле.","І, переправившись, були в землю Генісаретську і причалили до берега.","Коли вони вийшли з човна, відразу жителі, впізнавши Його,","оббігли всю околицю ту і почали приносити на постелях недужих туди, де тільки чули, що Він є.","І куди тільки не приходив Він, чи в села, чи в міста, чи в селища, на перехрестях клали недужих і просили Його, щоб їм доторкнутись хоч до краю одежі Його; і ті, які доторкалися до Нього, зцілялись."],"x":{"1":"50.13.54|52.4.16","2":"50.7.28|51.1.27","3":"52.4.22|53.6.42","4":"32.12.6|50.13.57|52.4.24|53.4.44","6":"50.9.35","7":"50.10.1|52.9.1","11":"50.10.14|52.9.5|54.13.51|54.18.6","13":"55.5.14","14":"50.14.1|52.9.7","17":"52.3.19","18":"2.18.16|2.20.21","20":"50.21.26","30":"52.9.10","32":"50.14.13|52.9.10","34":"50.9.36","38":"50.14.17|52.9.13|53.6.9","46":"50.14.23","47":"53.6.16","52":"51.8.18","53":"50.14.34","55":"50.4.24"}},{"v":["Зібрались до Нього фарисеї і деякі з книжників, які прийшли з Єрусалима,","І, побачивши, що деякі з учеників Його їли хліб нечистими, тобто немитими, руками, докоряли їм.","Бо фарисеї і всі юдеї не їдять, не вимивши старанно рук, додержуючись передань предків.","І після торжища, доки не обмиються, не їдять. Є і багато іншого, чого у них прийнято дотримуватись: обмивання чаш, кухлів, казанів і лавок.","Потім питають Його фарисеї і книжники: чому ученики Твої не роблять за переданням предків, а їдять хліб немитими руками?","Він сказав їм у відповідь: добре пророкував Ісая про вас, лицемірів, як і написано: люди ці шанують Мене устами, серце ж їхнє далеко від Мене.","Марно ж шанують Мене, навчаючи вчень, заповідей людських.","Бо ви, залишивши заповідь Божу, дотримуєтесь передання людського, обмиваєте чаші і кухлі і робите багато іншого, до цього подібного.","І сказав їм: чи добре, що відкидаєте заповідь Божу, щоб дотримуватися свого передання?","Бо Мойсей сказав: шануй батька свого і матір свою; і: хто лихословить на батька або матір, нехай смертю помре.","А ви кажете: якщо скаже людина батькові чи матері: «корван», тобто дар Богові те, чим би ти скористався від мене,","то вже дозволено нічого не робити для батька свого або матері своєї.","Переступаєте слово Боже переданням вашим, яке ви ж і установили; і робите багато чого, до цього подібного.","І, покликавши весь народ, говорив йому: слухайте Мене всі і розумійте:","нічого нема поза людиною, що входило б у неї і оскверняло її; але те, що виходить з неї, — те й оскверняє людину.","Якщо хто має вуха слухати, нехай слухає!","І коли Він увійшов у дім від народу, ученики Його спитали Його про притчу.","Він сказав їм: невже ви такі нерозумні? Невже не розумієте, що все те, що входить у людину ззовні, не може осквернити її?","Бо входить їй не в серце, а в утробу, і виходить геть, чим очищається всяка їжа.","Далі сказав: те, що виходить з людини, оскверняє людину.","Бо зсередини, від серця людського, виходять лихі помисли, перелюбства, любодійства, вбивства,","злодійство, здирство, лукавство, зради, ганебні вчинки, заздрісне око, богохульство, гордощі, безумство, —","все це зло зсередини виходить і оскверняє людину.","І підвівшись, пішов звідти у краї Тирські та Сидонські; і, увійшовши в дім, не хотів, щоб хтось пізнав Його; але не зміг утаїтися.","Бо почула про Нього жінка, в якої дочка мала нечистого духа, прийшла і припала до ніг Його;","а жінка та була язичниця, родом сирофінікіянка; і благала Його, щоб вигнав біса з дочки її.","Ісус же сказав їй: дай перше насититися дітям, бо недобре взяти хліб у дітей і кинути псам.","Вона ж сказала Йому у відповідь: так, Господи; але і пси під столом їдять крихти від дітей.","І сказав їй: за це слово, іди; вийшов біс із дочки твоєї.","І, прийшовши до свого дому, вона знайшла, що біс вийшов, і дочка лежить на постелі.","Вийшовши з країв Тирських і Сидонських, Ісус знову пішов до моря Галилейського через околиці Десятиграддя.","І привели до Нього глухого й гугнявого, і благали Його, щоб поклав на нього руку.","Ісус, одвівши його одного вбік від народу, вклав пальці Свої у вуха його і, сплюнувши, доторкнувся до його язика.","І, звівши очі на небо, зітхнув і сказав йому: «єффафа», тобто відкрийся.","І відразу відкрився у нього слух, і розв’язались пута язика його, і почав говорити правильно.","І наказав їм, щоб нікому не розповідали. Та скільки Він не забороняв їм, вони ще більше розголошували.","І надзвичайно дивувалися, кажучи: все добре робить, — глухим дає чути, і німим — говорити."],"x":{"1":"50.15.1","6":"50.15.8","7":"31.29.13|73.1.14","10":"1.20.12|1.21.17|30.3.7|50.15.4","15":"50.15.11|62.14.17|73.1.15","21":"0.8.21|26.6.14|32.17.9|50.15.19","24":"50.15.21","31":"50.15.29","37":"31.35.6"}},{"v":["У ті дні, коли зібралося дуже багато народу і нічого було їм їсти, Ісус, покликавши учеників Своїх, сказав їм:","жаль Мені людей, що вже три дні знаходяться зі Мною і нічого їм їсти.","Якщо відпущу їх голодними до своїх домів, ослабнуть у дорозі, бо багато з них прийшли здалека.","Ученики Його відповіли Йому: звідки міг би хто нагодувати їх хлібом тут, у пустелі?","І запитав у них: скільки у вас хлібів? Вони сказали: сім.","Тоді звелів народові сісти на землю; і, взявши сім хлібів і воздавши хвалу, переломив і дав ученикам Своїм, щоб вони роздали; і вони роздали людям.","Мали вони і трохи риби; благословивши, Він звелів роздати і її.","І їли, і наситились; і набрали залишків сім кошиків.","А тих, що їли, було близько чотирьох тисяч. І відпустив їх.","І, відразу увійшовши у човен з учениками Своїми, прибув у краї Далмануфанські.","Вийшли фарисеї, почали сперечатися з Ним і вимагали від Нього знамення з неба, спокушаючи Його.","І Він, тяжко зітхнувши, сказав: чого рід цей вимагає знамення? Істинно кажу вам: не дасться родові цьому знамення.","І, залишивши їх, знову увійшов у човен і відбув на той бік.","При цьому ученики Його забули взяти хлібів і, крім однієї хлібини, не мали з собою в човні нічого.","А Він заповідав їм, кажучи: глядіть, стережіться закваски фарисейської і закваски Іродової.","І, розмірковуючи, один одному говорили, що хлібів немає у них.","Ісус, зрозумівши, говорить їм: чого ви міркуєте про те, що немає у вас хлібів? Чи ще не збагнули і не розумієте? Чи ще окам’яніле у вас серце?","Маючи очі, не бачите, маючи вуха, не чуєте?","Чи не пам’ятаєте, коли Я п’ять хлібів переломив для п’яти тисяч чоловік, скільки повних кошиків набрали ви залишків? Говорять Йому: дванадцять.","А коли сім для чотирьох тисяч, скільки кошиків набрали ви того, що залишилося? Сказали: сім.","І сказав їм: як же не розумієте?","Приходить до Вифсаїди; і приводять до Нього сліпого, і благають, щоб доторкнувся до нього.","Він, взявши сліпого за руку, вивів його геть із села, і, плюнувши йому на очі його, поклав на нього руки і запитав його, чи бачить що.","Він, глянувши, сказав: бачу, мов дерева, людей, що проходять.","Потім знову поклав руки на очі йому і велів йому прозріти. І він зцілився, і став бачити все ясно.","І послав його додому, кажучи: не заходь у село і нікому в селі не розповідай.","І пішов Ісус з учениками Своїми в села Кесарії Филипової. Дорогою Він питав учеників Своїх: за кого вважають Мене люди?","Вони відповідали: за Іоана Хрестителя, інші ж — за Іллю, а деякі — за одного з пророків.","Він говорить їм: а ви за кого Мене вважаєте? Петро сказав Йому у відповідь: Ти є Христос.","І заборонив їм, щоб нікому не говорили про Нього.","І почав навчати їх, що Сину Людському належить багато постраждати, і відцураються від Нього старійшини, первосвященики та книжники, і буде вбитий, і на третій день воскресне.","І говорив про це відкрито. Але Петро, відізвавши Його, почав перечити Йому.","Він же, обернувшись і глянувши на учеників Своїх, заборонив Петрові, кажучи: відійди від Мене, сатано, бо ти думаєш не про те, що Боже, а що людське.","І, покликавши народ з учениками Своїми, сказав їм: хто хоче йти за Мною, нехай зречеться себе, і візьме хрест свій, і за Мною йде.","Бо хто хоче душу свою спасти, той погубить її; а хто погубить душу свою заради Мене і Євангелія, той спасе її.","Бо яка користь людині, коли вона придбає ввесь світ, а душу свою занапастить?","Або що дасть людина взамін за душу свою?","Бо якщо хтось посоромиться Мене і Моїх слів у роді цьому перелюбному і грішному, того посоромиться і Син Людський, коли прийде у славі Отця Свого з ангелами святими."],"x":{"1":"50.15.32","10":"50.15.39","11":"50.16.1","15":"50.16.6|52.12.1","18":"51.6.38|53.6.9","27":"50.16.13|52.9.18","29":"53.6.69","31":"51.9.31|51.10.33|52.9.22","34":"50.10.38|50.16.24|52.9.23|52.14.27","37":"25.48.9","38":"50.10.33|52.9.26|58.2.23|62.1.16|72.2.12"}},{"v":["І сказав їм: істинно говорю вам, що деякі з тих, які стоять тут, не зазнають смерти, доки не побачать Царство Боже, що прийшло в силі.","І через шість днів узяв Ісус Петра, Якова та Іоана, і вивів лише їх одних на гору високу, і преобразився перед ними.","Одяг Його став блискучим, дуже білим, мов сніг, як жоден білильник не може вибілити на землі.","І явилися їм Ілля з Мойсеєм, і розмовляли з Ісусом.","При цьому Петро сказав Ісусові: Учителю, добре нам тут бути; зробимо три намети: Тобі один, Мойсеєві один та Іллі один.","Бо не знав, що сказати; тому що страх охопив їх.","І з’явилася хмара, і осінила їх, і пролунав голос із хмари, кажучи: Цей є Син Мій Улюблений, Його слухайте!","І тут же, поглянувши, нікого вже не побачили, крім одного Ісуса з собою.","Коли ж вони сходили з гори, Він наказав їм нікому не розповідати про те, що бачили, доки Син Людський не воскресне з мертвих.","І вони тримали в собі це слово, допитуючись: що то означає, — воскреснути з мертвих.","І спитали Його: як же книжники говорять, що раніше належить прийти Іллі?","Він же відповів їм: Ілля повинен прийти раніш і приготувати все; і як написано про Сина Людського, Йому належить багато постраждати і бути зневаженим.","Але кажу вам, що Ілля прийшов, і вчинили йому, як хотіли, як написано про нього.","Прийшовши до учеників, побачив багато народу біля них і книжників, які сперечалися з ними.","І відразу, побачивши Його, всі люди здивувалися, і, підбігаючи, вітали Його.","Він запитав книжників: про що сперечаєтеся між собою?","Один з натовпу сказав у відповідь: Учителю, я привів до Тебе мого сина, що має духа німого.","Де тільки нападе на нього, кидає його на землю, і він пускає піну, і скрегоче зубами своїми, і ціпеніє. Я казав ученикам Твоїм, щоб вигнали його, та вони не змогли.","Він же, відповідаючи йому, сказав: о роде невірний, доки буду з вами? Доки буду терпіти вас? Приведіть його до Мене.","І привели його до Нього. Побачивши Його, дух стряснув його; він упав на землю і валявся, пускаючи піну.","Ісус запитав батька його: скільки років, як це сталося з ним? Він сказав: з дитинства;","багато разів дух кидав його і в огонь і у воду, щоб згубити його; але, якщо можеш, допоможи нам, змилосердься над нами.","Ісус сказав йому: якщо хоч трохи можеш вірувати, все можливе віруючому.","І тут же скрикнув батько отрока, зі сльозами говорячи: вірую, Господи! Допоможи моєму невірству.","Ісус, побачивши, що збігається народ, заборонив духові нечистому, сказавши йому: душе німий і глухий! Я тобі повеліваю: вийди з нього і більше не входь у нього.","І, закричавши та сильно напружившись, вийшов; і він став наче мертвий, так що багато хто говорив, що він помер.","Але Ісус, взявши його за руку, підняв його; і той устав.","Коли Ісус увійшов у дім, ученики спитали Його на самоті: чому ми не змогли вигнати його?","І сказав їм: цей рід не може вийти інакше, як від молитви і посту.","Вийшовши звідти, проходили через Галилею, і Він не хотів, щоб хто довідався.","Бо навчав учеників Своїх і говорив їм, що Сина Людського видано буде до рук людських, і вб’ють Його, і, вбитий будучи, Він на третій день воскресне.","Вони ж не розуміли цих слів, а запитати Його боялися.","Прийшли до Капернаума; і коли був у домі, запитав їх: про що дорогою ви міркували між собою?","Вони мовчали, бо дорогою сперечалися між собою, хто більший.","І, сівши, запросив дванадцятьох і сказав їм: хто хоче бути першим, нехай буде з усіх найменшим і всім слугою.","І, взявши дитину, поставив її посеред них і, обнявши її, сказав їм:","хто одного з таких дітей прийме в ім’я Моє, той Мене приймає; а хто Мене приймає, той не Мене приймає, але Того, Хто послав Мене.","Відповів Йому Іоан, сказавши: Учителю, ми бачили одного, який Твоїм іменем виганяє бісів, а не ходить за нами; і заборонили йому, бо він не йде слідом за нами.","Ісус сказав: не бороніть йому, бо нема нікого, хто сотворить чудо в ім’я Моє і зможе скоро лихословити на Мене.","Бо хто не проти вас, той за вас.","І хто напоїть вас чашею води в ім’я Моє, тому що ви Христові, істинно кажу вам, не втратить своєї нагороди.","А хто спокусить одного з малих цих, віруючих у Мене, тому краще було б, якби повісили йому камінь жорновий на шию і кинули його в море.","І якщо спокушає тебе рука твоя, відсічи її; краще тобі калікою ввійти в життя, ніж, дві руки маючи, йти в геєну, в огонь невгасимий,","де черв їхній не вмирає і вогонь не вгасає.","І якщо нога твоя спокушає тебе, відсічи її; краще тобі кривим увійти в життя, ніж, дві ноги маючи, бути вкинутим у геєну, в огонь невгасимий,","де черв їхній не вмирає і вогонь не вгасає.","І якщо око твоє спокушає тебе, вирви його: краще тобі з одним оком увійти в Царство Боже, ніж, два ока маючи, бути вкинутим у геєну вогненну,","де черв їхній не вмирає і вогонь не вгасає.","Бо кожний вогнем осолиться, і всяка жертва сіллю посолиться.","Сіль — добра річ; якщо ж сіль не солона буде, чим осолиться? Майте сіль у собі і майте мир між собою."],"x":{"1":"50.16.28|52.9.27","2":"50.17.1","11":"50.17.10","12":"25.21.7|31.53.3|37.7.13|37.9.26","13":"49.4.5|50.17.12","17":"50.17.14|52.9.38","23":"50.17.20|50.21.22","31":"50.17.22|52.9.22|52.24.7","36":"50.18.5|52.9.48","38":"52.9.49","39":"63.12.3","41":"50.10.42","42":"4.13.6-10|50.18.6|52.17.1","43":"50.5.29|50.18.8","44":"31.66.24","49":"2.2.13|36.43.24","50":"50.5.13|62.14.19|68.4.6"}},{"v":["Вийшовши звідти, приходить у краї Юдейські, по той бік Йордану. Знову збирається до Нього народ, і, за звичаєм Своїм, Він знову навчав їх.","Підійшли фарисеї і запитали, спокушаючи Його: чи дозволено чоловікові розводитися з жінкою?","Він сказав їм у відповідь: що вам заповів Мойсей?","Вони сказали: Мойсей дозволив написати розвідний лист і розлучатись.","Ісус відповів їм: через жорстокосердя ваше написав вам заповідь цю.","На початку ж творіння чоловіком і жінкою створив їх Бог.","Ось чому залишить чоловік батька свого і матір","і пристане до жінки своєї, і будуть обоє єдиною плоттю. Так що вони вже не двоє, а одна плоть.","Отже, що Бог з’єднав, того людина нехай не розлучає.","У домі ученики Його знову запитали Його про те саме.","Він сказав їм: хто розведеться з жінкою своєю та ожениться на іншій, той перелюб чинить з нею.","І якщо жінка розведеться з чоловіком своїм і вийде за іншого, перелюб чинить.","Приносили до Нього дітей, щоб Він доторкнувся до них; ученики ж не допускали тих, що приносили.","Побачивши те, Ісус обурився і сказав їм: дозволяйте дітям приходити до Мене і не забороняйте їм, бо таких є Царство Боже.","Істинно кажу вам: хто не прийме Царства Божого, як дитина, той не ввійде в нього.","І, обнявши їх, покладав руки на них і благословляв їх.","Коли виходив Він у дорогу, підбіг один якийсь, упав перед Ним на коліна і запитав Його: Учителю благий, що мені робити, щоб життя вічне успадкувати?","Ісус сказав йому: чому ти називаєш Мене благим? Ніхто не благий, тільки один Бог.","Заповіді знаєш: не чини перелюбу, не вбивай, не кради, не лжесвідчи, не кривди, шануй батька твого і матір.","Той же сказав Йому у відповідь: Учителю, всього цього я дотримувався від юности моєї.","Ісус, поглянувши на нього з любов’ю, сказав йому: одного тобі не вистачає: піди і все, що маєш, продай і роздай убогим; і матимеш скарб на небесах; тоді приходь та іди вслід за Мною, взявши хрест.","Він же, засмутившись від цього слова, відійшов зі скорботою, бо мав велике багатство.","І, поглянувши довкола, Ісус сказав ученикам Своїм: як тяжко тим, хто має багатство, увійти в Царство Боже.","Ученики вжахнулись від слів Його. Але Ісус знову говорить їм у відповідь: діти, як тяжко тим, хто надіється на багатство, увійти в Царство Боже!","Бо легше верблюдові пройти крізь вушко голки, ніж багатому ввійти в Царство Боже.","Вони ж надзвичайно здивувалися і говорили між собою: хто ж може спастись?","Ісус, глянувши на них, говорить: для людей це неможливо, та не для Бога, бо все можливо Богові.","І почав Петро говорити Йому: ось ми все залишили і пішли слідом за Тобою.","Ісус же відповів: істинно говорю вам: нема нікого, хто залишив би дім, чи братів, чи сестер, чи батька, чи матір, чи жінку, чи дітей, чи землю ради Мене і ради Євангелія","і не одержав би сторицею вже нині, в час цей, серед гонінь, — домів, і братів, і сестер, і батьків, і матерів, і дітей, і земель, а в грядущому віці — життя вічне.","І багато хто з перших будуть останніми, а останні — першими.","Коли вони були в дорозі, йдучи до Єрусалима, Ісус ішов попереду них, а вони жахалися і, йдучи за Ним слідом, боялися.","Покликавши знову дванадцятьох, Він почав їм говорити про те, що буде з Ним: ось ми йдемо до Єрусалима, і Син Людський виданий буде первосвященикам і книжникам, і осудять Його на смерть, і видадуть Його язичникам;","і знущатимуться з Нього, і битимуть Його, і обплюють Його, і уб’ють Його; і на третій день воскресне.","Тоді підійшли до Нього Яків та Іоан, сини Зеведеєві, і сказали: Учителю, ми хочемо, щоб Ти зробив нам, про що попросимо.","Він сказав їм: що хочете, щоб Я зробив вам?","Вони сказали Йому: дай нам одному праворуч від Тебе, а другому ліворуч від Тебе сісти у славі Твоїй.","Ісус же сказав їм: не знаєте, чого просите. Чи можете пити чашу, яку Я п’ю, і хрещенням, яким Я хрещусь, хреститися?","Вони відповіли Йому: можемо. Ісус же сказав їм: чашу, яку Я п’ю, вип’єте, і хрещенням, яким Я хрещусь, охреститеся;","але щоб сісти праворуч і ліворуч від Мене — не від Мене залежить, а кому уготовано.","І, почувши, десять почали гніватись на Якова та Іоана.","Ісус же, покликавши їх, сказав їм: ви знаєте, що ті, яких називають князями народів, панують над ними, і вельможі їхні володіють ними.","Але між вами нехай не буде так: хто хоче бути більшим між вами, нехай буде вам слугою.","І хто хоче бути першим між вами, нехай буде всім рабом.","Бо і Син Людський не для того прийшов, щоб Йому служили, але щоб послужити і віддати душу Свою за визволення багатьох.","Приходять до Єрихона. І коли Він з учениками Своїми і численним людом виходив з Єрихона, син Тимеїв, Вартимей, сліпий, сидів при дорозі і просив милостиню.","Почувши, що це Ісус Назорей, він почав кричати і говорити: Ісусе, Сину Давидів! Помилуй мене.","І примушували його мовчати багато хто, він же ще більше кричав: Сину Давидів, помилуй мене!","Ісус зупинився і сказав його покликати. Кличуть сліпого і кажуть йому: не бійся, вставай, кличе тебе.","Той скинув з себе верхній одяг, встав і прийшов до Ісуса.","Відповідаючи йому, Ісус спитав: чого ти хочеш від Мене? Сліпий сказав Йому: Учителю, аби я прозрів.","Ісус сказав йому: йди, віра твоя спасла тебе. І відразу він прозрів, і пішов дорогою за Ісусом."],"x":{"2":"50.19.3","4":"4.24.1|50.5.31|52.16.18","6":"0.1.27|50.19.4","7":"63.6.16","8":"0.2.24","9":"63.7.10","13":"50.19.13|52.18.15","14":"50.18.4|56.2.2|63.14.20","15":"50.11.25","16":"50.19.15","17":"50.19.16|52.18.18","19":"1.20.12-17|4.5.17|50.5.21|52.18.20","21":"50.6.19","23":"24.31.24|55.2.5|71.6.17","27":"24.42.2","28":"50.19.27|52.18.28","31":"50.19.30|52.13.30","33":"50.20.18|52.18.31","35":"50.20.20","41":"50.20.24|52.22.24","44":"51.9.35","45":"53.13.15|56.5.3|67.2.7","46":"50.20.29"}},{"v":["Коли наблизились до Єрусалима, до Виффагії та Вифанії, до гори Елеонської, Ісус посилає двох з учеників Своїх","і говорить їм: підіть у селище, яке прямо перед вами; і як тільки ввійдете в нього, зараз же знайдете осля прив’язане, на якого ніхто з людей ще не сідав; відв’язавши його, приведіть.","І якщо хто скаже вам: що це ви робите, — відповідайте, що Господь потребує його; і відразу ж пошле його сюди.","Вони пішли і знайшли молодого осла, прив’язаного на вулиці біля воріт, і відв’язали його.","І деякі з тих, що там стояли, говорили їм: що робите, навіщо відв’язуєте осля?","Вони відповіли їм, як велів Ісус, і ті відпустили їх.","І привели осля до Ісуса; і поклали на нього одяг свій; і сів на нього.","Багато хто стелив свій одяг по дорозі; а інші різали гілки з дерев і встилали ними дорогу.","І ті, які пішли попереду Нього, і ті, які супроводжували Його, викликували: осанна! Благословен, Хто гряде в ім’я Господнє!","Благословенне Царство отця нашого Давида, що гряде в ім’я Господнє! Осанна у вишніх!","І ввійшов Ісус в Єрусалим і в храм; і, оглянувши все, оскільки час уже був пізній, пішов до Вифанії з дванадцятьма.","На другий день, коли вони вийшли з Вифанії, зголоднів.","І, побачивши здалека смоковницю, вкриту листям, пішов, чи не знайде чого на ній; але, прийшовши до неї, нічого не знайшов, крім листя, бо ще не час був для смокв.","І сказав їй Ісус: віднині нехай довіку ніхто плоду твого не з’їсть. І чули те ученики Його.","Прийшли до Єрусалима. Ісус, увійшовши до храму, почав виганяти тих, що продавали і купували в храмі; і столи міняйл, і лави тих, що продавали голубів, поперекидав.","І не дозволяв, щоб хто переніс через храм будь-яку річ.","І вчив їх, кажучи: чи не написано: дім Мій домом молитви назветься для всіх народів? Ви ж зробили його вертепом розбійників.","Почули це книжники і первосвященики і шукали, як би погубити Його, але боялися, тому що весь народ дивувався Його вченню.","Коли ж стало пізно, Він вийшов геть з міста.","Проходячи вранці, побачили смоковницю, що всохла до кореня.","І, згадавши, Петро сказав Йому: Учителю, дивись, смоковниця, яку Ти прокляв, усохла.","Ісус, відповідаючи, говорить їм:","майте віру Божу, бо істинно кажу вам, якщо хто скаже горі цій: посунься і кинься в море, і не сумніватиметься в серці своїм, а повірить, що станеться за його словом, — буде йому, що тільки скаже.","Тому кажу вам: усе, чого ви попросите в молитві, вірте, що одержите, — і буде вам.","І коли стоїте на молитві, прощайте, коли щось маєте на кого, щоб і Отець ваш Небесний відпустив вам гріхи ваші.","Якщо ж не прощаєте, то і Отець ваш Небесний не відпустить вам гріхів ваших.","Прийшли знову до Єрусалима. І коли Він ходив у храмі, підійшли до Нього первосвященики, і книжники, і старійшини","і говорили Йому: якою владою Ти це робиш? І хто дав Тобі владу це робити?","Ісус сказав їм у відповідь: запитаю і Я вас про одне, відповідайте Мені; тоді і Я скажу вам, якою владою це роблю.","Хрещення Іоанове з небес було чи від людей? Скажіть Мені.","Ті міркували між собою: якщо скажемо, що з небес, то Він скаже: чому ж ви не повірили йому?","А сказати, що від людей, — боялись народу; бо всі знали, що Іоан воістину був пророк.","І сказали у відповідь Ісусові: не знаємо. Тоді Ісус сказав їм у відповідь: і Я не скажу вам, якою владою це роблю."],"x":{"1":"50.21.1|52.19.29","7":"50.21.7|52.19.35","8":"53.12.13","9":"25.117.26","15":"50.21.12|52.19.45|53.2.14","17":"31.56.7|32.7.11","24":"50.7.7|52.11.9|53.14.13","25":"30.28.2|50.6.14|66.4.32|68.3.13","27":"50.21.23|52.20.1"}},{"v":["І почав говорити їм притчами: один чоловік насадив виноградник і обгородив плотом, і викопав виностік*, і збудував башту, і, передавши все виноградарям, від’їхав.","І послав у свій час до виноградарів слугу — одержати від виноградарів плоди з виноградника.","Вони ж, схопивши його, били і відіслали ні з чим.","Знову послав до них іншого слугу; і тому камінням розбили голову і відіслали з безчестям.","І знову іншого послав, і того вбили; і багатьох інших — одних били, інших вбивали.","Маючи ж єдиного сина, улюбленого свого, наостанку послав і його до них, кажучи: посоромляться сина мого.","Але виноградарі сказали один одному: це спадкоємець, ходім уб’ємо його, і спадщина буде наша.","І, схопивши його, вбили і викинули геть з виноградника.","Що ж зробить господар виноградника? Прийде і покарає виноградарів смертю, і віддасть виноградник іншим.","Невже ви не читали цього в Писанні: камінь, який відкинули будівничі, той самий став наріжним каменем.","Це від Господа, і дивним є в очах наших.","І шукали нагоди схопити Його, але побоялися народу, бо зрозуміли, що про них сказав притчу; і, залишивши Його, відійшли.","І посилають до Нього декого з фарисеїв та іродіан, щоб спіймати Його на слові.","Вони ж, прийшовши, говорять Йому: Учителю, ми знаємо, що Ти справедливий і не прагнеш будь-кому догодити, бо не зважаєш на особу, а воістину навчаєш путі Божої. Чи дозволено платити податок кесареві, чи ні? Давати нам чи не давати?","Але Він, знаючи їхнє лицемірство, сказав їм: чого спокушаєте Мене? Принесіть Мені динарій, щоб Я побачив його.","Вони принесли. Тоді говорить їм: чиє це зображення і напис? Вони ж сказали: кесаря.","Ісус сказав їм у відповідь: віддайте кесареве кесарю, а Боже Богові. І дивувалися Йому.","Потім прийшли до Нього саддукеї, які кажуть, що не існує воскресіння, і запитали Його, кажучи:","Учителю! Мойсей написав нам: якщо в кого помре брат і залишить жінку, то брат його нехай візьме жінку його і відродить потомство братові своєму.","Було сім братів: перший узяв жінку і помер, не залишивши дітей.","Узяв її другий і помер, і він теж не залишив дітей; і третій так само.","Брали її за себе семеро і не залишили дітей. Після всіх померла й жінка.","Отже, в час воскресіння, коли воскреснуть, котрого з них буде вона жінкою? Бо семеро мали її за жінку.","Ісус сказав їм у відповідь: чи не тому ви й помиляєтеся, що не знаєте ні Писання, ані сили Божої?","Бо, коли воскреснуть з мертвих, тоді не будуть ні женитися, ні заміж виходити, а будуть як ангели на небесах.","А про мертвих, що вони воскреснуть, хіба не читали ви в книзі Мойсея, як при купині Бог сказав йому: Я Бог Авраама, і Бог Ісаака, і Бог Якова?","Бог не є Бог мертвих, а Бог живих. Отже, ви дуже помиляєтесь.","І приступив один з книжників, що слухав, як вони сперечалися, і бачив, як добре Ісус відповів їм, і спитав Його: яка заповідь перша з усіх заповідей?","Ісус відповів йому: перша з усіх заповідей: слухай, Ізраїлю! Господь Бог наш є Господь єдиний.","І полюби Господа Бога твого всім серцем твоїм, і всією душею твоєю, і всім розумінням твоїм, і всією силою твоєю, — ось перша заповідь!","І друга подібна до неї: полюби ближнього твого, як самого себе. Більшої за ці заповіді немає.","Книжник сказав Йому: добре, Учителю! Ти істину сказав, що один є Бог, і немає іншого, крім Нього;","і любити Його всім серцем, і всім розумом, і всією душею, і всією силою, і любити ближнього, як самого себе, є більше за всі всепалення і жертви.","Ісус, побачивши, що він розумно відповів, сказав йому: ти недалеко від Царства Божого. Після того ніхто не насмілився питати Його.","Продовжуючи навчати в храмі, Ісус говорив: як це кажуть книжники, що Христос є син Давидів?","Бо сам Давид сказав Духом Святим: сказав Господь Господеві моєму: сиди праворуч Мене, доки покладу ворогів Твоїх — підніжжям ніг Твоїх.","Отже, сам Давид називає Його Господом — як же Він син йому? І багато народу слухало Його з насолодою.","І говорив їм у вченні Своїм: стережіться книжників, які люблять ходити в довгому одязі і приймати вітання на народних зібраннях,","сидіти спереду в синагогах і возлежати на перших місцях на бенкетах, —","ції, котрі поїдають доми вдів і лицемірно довго моляться, приймуть найтяжче осудження.","І сів Ісус навпроти скарбниці і спостерігав, як народ кладе гроші в скарбницю. Чимало заможних клали багато.","Прийшла одна вбога вдова і поклала дві лепти, тобто кодрант.","Покликавши учеників Своїх, Ісус сказав їм: істинно кажу вам, що ця вбога вдова поклала більше за всіх, хто клав у скарбницю,","бо всі клали з достатку свого, а вона із злиднів своїх поклала все, що мала, весь прожиток свій."],"x":{"1":"25.79.9|28.8.12|31.5.1|50.21.33","3":"50.5.12|50.23.34","7":"50.26.3-4","8":"75.13.12","10":"50.21.42","11":"25.117.22-23","13":"50.22.15|52.20.20","17":"50.22.21","18":"52.20.27","19":"4.25.5|50.22.24|52.20.28","26":"1.3.6|50.22.32|52.20.37","28":"50.22.35|52.10.25","29":"50.22.37|52.10.27","30":"4.6.4-5","31":"2.19.18|50.5.43|55.2.8|62.13.9|65.5.14","35":"50.22.41|52.20.41","36":"25.109.1","39":"50.23.6|52.11.43","40":"36.22.25|52.20.47","41":"52.21.1"},"n":{"1":["Яма для видушування винограду."]}},{"v":["І коли виходив Він з храму, один з учеників Його сказав Йому: Учителю, подивись, які камені і які будівлі!","Ісус сказав йому у відповідь: бачиш ці великі будівлі? Все це буде зруйноване, так що не залишиться тут і каменя на камені.","І коли Він сидів на горі Елеонській проти храму, то Петро, Яків, Іоан і Андрій запитали Його на самоті:","скажи нам, коли це буде, і яке знамення, коли все це має скінчитися?","Відповідаючи їм, Ісус почав говорити: бережіться, щоб ніхто не спокусив вас,","бо багато хто прийде під іменем Моїм і говоритиме, що це Я; і багатьох спокусять.","Коли ж почуєте про війни і воєнні чутки, не жахайтеся: бо належить цьому бути, — але це ще не кінець.","Бо постане народ на народ і царство на царство; і будуть землетруси у різних місцях, і будуть голод і заворушення; це — початок хвороб.","Стережіться ж ви самі, бо вас видаватимуть на судища і битимуть у синагогах, і перед правителями і царями поставлять вас через Мене, на свідчення перед ними.","І всім народам раніш повинно бути проповідане Євангеліє.","Коли ж поведуть видавати вас, то не турбуйтесь заздалегідь, що вам говорити, і не обдумуйте; але, що дасться вам у той час, те й говоріть, бо не ви будете говорити, а Дух Святий.","Видасть же брат брата на смерть, і батько — дітей; і постануть діти на батьків, і уб’ють їх.","І ненавидітимуть вас усі за ім’я Моє; хто ж перетерпить до кінця, той спасеться.","Коли ж побачите мерзоту запустіння, провіщену пророком Даниїлом, яка стоятиме, де не належить, хто читає, нехай розуміє, тоді хто буде в Юдеї, нехай біжить у гори;","а хто на покрівлі, той нехай не сходить у дім і не заходить узяти щось з дому свого;","і хто на полі, нехай не вертається назад взяти одяг свій.","Горе ж вагітним і матерям-годувальницям у ті дні!","Моліться, щоб не сталася втеча ваша взимку.","Бо в ті дні буде така скорбота, якої не було від початку творіння, яке вчинив Бог, навіть і донині, і не буде.","І коли б Господь не вкоротив тих днів, то не спаслась би ніяка плоть; але заради обраних, яких Він обрав, укоротить дні.","Тоді, якщо хто скаже вам: ось, тут Христос, або: ось там, — не йміть віри.","Бо встануть лжехристи і лжепророки і дадуть знамення і чудеса, щоб спокусити, якщо можливо, і обраних.","Ви ж бережіться. Ось, Я наперед сказав вам усе.","Але в ті дні, після тієї скорботи, сонце померкне, і місяць не дасть свого світла,","і зірки спадуть з неба, і сили небесні похитнуться.","І тоді побачать Сина Людського, Який гряде на хмарах, з силою і славою великою.","І тоді Він пошле ангелів Своїх і збере обраних Своїх від чотирьох вітрів, від краю землі до краю неба.","Від смоковниці навчіться притчі: коли гілля її стає вже м’яким і пускає листя, то знаєте, що близько літо.","Так і ви: коли побачите, що все збувається, знайте, що близько, при дверях.","Істинно кажу вам: не перейде рід цей, як усе це буде.","Небо і земля перейдуть, слова ж Мої не перейдуть.","Про день же той або про годину ніхто не знає: ні ангели небесні, ні Син, а тільки Отець.","Пильнуйте, будьте на сторожі і моліться, бо не знаєте, коли настане час цей.","Подібно до того, коли чоловік, відходячи в дорогу і залишаючи свій дім, дав владу слугам своїм, і кожному своє діло, і наказав воротареві пильнувати,","так і ви: пильнуйте, бо не знаєте, коли прийде господар дому, ввечері, чи опівночі, чи як півні заспівають, чи вранці.","Щоб, коли він несподівано прийде, ви не спали.","А що кажу вам, кажу всім: пильнуйте."],"x":{"1":"50.24.1|52.21.5","2":"52.19.44|52.21.6","5":"50.24.4|52.21.8|66.5.6|70.2.3","9":"53.15.20","11":"50.10.19|52.12.11","14":"37.9.27|50.24.15|52.21.20","21":"50.24.23|52.17.23","24":"31.13.10|36.32.7|39.2.31|50.24.29|52.21.25","26":"50.24.30|76.1.7","30":"50.24.34","33":"50.24.42|50.25.13"}},{"v":["Через два дні мало бути свято Пасхи і опрісноків. І шукали первосвященики і книжники, як би взяти Його хитрощами і вбити.","Але говорили: тільки не в свято, щоб не сталося заворушення в народі.","І коли Він був у Вифанії, в домі Симона прокаженого, і возлежав, — прийшла жінка з алавастровою посудиною мира з нарда чистого, дорогоцінного, і, розбивши посудину, злила Йому на голову.","Деякі обурились і між собою говорили: навіщо така трата мира?","Бо можна було б його продати більш як за триста динаріїв і роздати вбогим. І дорікали їй.","Ісус же сказав: облиште її, навіщо її бентежите? Вона добре діло зробила для Мене.","Бо вбогих завжди маєте з собою і, коли захочете, можете їм добро робити; Мене ж не завжди маєте.","Вона зробила, що могла: заздалегідь помазала Моє тіло на погребіння.","Істинно кажу вам: по всьому світу, де тільки буде проповідане це Євангеліє, буде сказано на спомин про неї і про те, що вона зробила.","І пішов Іуда Іскаріотський, один з дванадцяти, до первосвящеників, щоб видати Його їм.","Вони ж, почувши, зраділи і пообіцяли дати йому срібників. І він шукав, як би в слушний час видати Його.","У перший день опрісноків, коли готували пасхальне ягня, ученики сказали Йому: де хочеш їсти паску? Ми підемо і приготуємо.","І посилає двох з учеників Своїх, і каже їм: підіть до міста, і зустрінеться вам чоловік, який нестиме глек води; підіть за ним,","і куди він увійде, скажіть господареві дому того, що Учитель каже — де світлиця, в якій Я споживатиму паску з Моїми учениками?","І він покаже вам велику, прибрану і готову горницю; там приготуйте нам.","І пішли ученики Його, і прийшли до міста, і знайшли, як сказав їм; і приготували паску.","Як настав вечір, Він прийшов з дванадцятьма.","І коли вони возлежали і їли, Ісус сказав: істинно кажу вам, один з вас, що їсть зі Мною, зрадить Мене.","Вони засмутились і почали говорити Йому один за одним: чи не я? І інший: чи не я?","Він же сказав їм у відповідь: один з дванадцяти, який умочає зі Мною в блюдо.","Та Син Людський іде, як написано про Нього; але горе тій людині, якою Син Людський буде зраджений: краще було б не народитися людині тій.","І коли вони їли, Ісус узяв хліб, благословив, переламав, дав їм і сказав: прийміть, споживайте, це є Тіло Моє.","І, взявши чашу та хвалу воздавши, подав їм; і пили з неї всі.","І сказав їм: це є Кров Моя Нового Завіту, що за багатьох проливається.","Істинно кажу вам: Я вже не питиму від плоду виноградного до того дня, коли питиму нове вино в Царстві Божому.","І, проспівавши, пішли на гору Елеонську.","І сказав їм Ісус: цієї ночі всі ви спокуситеся через Мене, бо написано: уражу пастиря, і розбіжаться вівці.","По воскресінні ж Моїм буду раніше за вас у Галилеї.","Петро сказав Йому: хоч і всі спокусяться, але не я.","І говорить йому Ісус: істинно кажу тобі, що сьогодні, цієї ночі, раніше, ніж двічі проспіває півень, ти тричі зречешся Мене.","Він же ще більше запевняв: хоч би мені належало і вмерти з Тобою, не зречуся Тебе. Так само і всі говорили.","Прийшли до місця, що зветься Гефсиманія; і Він сказав ученикам Своїм: посидьте тут, поки Я помолюся.","І взяв з Собою Петра, Якова та Іоана; і почав тужити й сумувати.","І сказав їм: сумна душа Моя смертельно; побудьте тут і пильнуйте.","І, трохи відійшовши, впав на землю і молився, щоб, коли можливо, минула Його година ця.","І говорив: Авва, Отче! Все можливе для Тебе, пронеси мимо Мене чашу цю; та не чого Я хочу, а чого Ти.","Повертається і знаходить їх сплячими, і каже Петрові: Симоне, чи ти спиш? Не міг ти пильнувати й однієї години?","Пильнуйте і моліться, щоб не зазнати спокуси: дух бадьорий, плоть же немічна.","І знову відійшов і молився, промовивши те саме слово.","І, повернувшись, знову знайшов їх сплячими; бо очі їхні обважніли, і вони не знали, що Йому відповідати.","І прийшов утретє і каже їм: ви все ще спите і спочиваєте? Годі, прийшов час: Син Людський видається в руки грішників.","Встаньте, підемо, ось наблизився той, хто видає Мене.","І зараз же, як Він ще говорив, прийшов Іуда, один з дванадцяти, і з ним багато народу з мечами та киями, від первосвящеників і книжників і старійшин.","Зрадник же Його подав їм знак, сказавши: Кого я поцілую, Той і є; беріть Його і ведіть обережно.","І, прийшовши, відразу підійшов до Нього і каже: Учителю! Учителю! І поцілував Його.","А вони наклали руки свої на Нього і взяли Його.","Один же з тих, що стояли тут, вихопив меча та вдарив раба первосвященика і відсік йому вухо.","Тоді Ісус сказав їм: ніби на розбійника вийшли ви з мечами та киями, щоб Мене взяти.","Повсякдень Я бував з вами в храмі і навчав, і ви не брали Мене. Але нехай збудуться Писання.","Тоді, залишивши Його, всі повтікали.","Один юнак, загорнувшись покривалом на голе тіло, йшов слідом за Ним; і воїни схопили його.","Але він, покинувши покривало, голим утік від них.","І привели Ісуса до первосвященика; і зібрались до нього всі первосвященики, і книжники, і старійшини.","Петро віддалік ішов слідом за Ним аж до середини двору первосвященика; і сидів зі слугами і грівся біля вогню.","Первосвященики ж і весь синедріон шукали свідчення на Ісуса, щоб віддати Його на смерть; і не знаходили.","Бо багато лжесвідчили на Нього, але ці свідчення не сходились.","І деякі, вставши, лжесвідчили проти Нього і говорили:","ми чули, як Він казав: Я зруйную храм цей рукотворний і через три дні зведу інший, нерукотворний.","Але й таке свідчення їхнє не сходилось.","Тоді первосвященик став посередині і спитав Ісуса: чого ж Ти нічого не відповідаєш на те, що вони проти Тебе свідчать?","Він же мовчав і нічого не відповідав. Знову первосвященик спитав Його і сказав Йому: чи Ти Христос, Син Благословенного?","Ісус сказав: Я! І ви побачите Сина Людського, Який сидить праворуч сили Божої і йде з хмарами небесними.","Тоді первосвященик, розірвавши одяг свій, сказав: для чого ще нам свідки?","Ви чули богохульство? Як вам здається? Вони ж усі засудили Його до смерти.","І деякі почали плювати на Нього і, закриваючи Йому лице, бити Його і говорити Йому: проречи. І слуги били Його по щоках.","Коли Петро був на подвір’ї внизу, прийшла одна із служниць первосвященика","і, побачивши Петра, який грівся, та придивившись до нього, сказала: і ти був з Ісусом Назарянином.","Але він відрікся, сказавши: не знаю і не розумію, що ти говориш. І вийшов геть на передній двір; і заспівав півень.","Служниця, побачивши його знову, почала говорити присутнім, що цей з них.","Він знову відрікся. Трохи згодом присутні знову стали говорити Петрові: та й справді ти з них, бо ти галилеянин, і мова твоя схожа.","Він же почав божитися і клястися: не знаю Чоловіка Цього, про Якого говорите.","Тоді вдруге заспівав півень. І згадав Петро слово, сказане йому Ісусом: перше ніж двічі проспіває півень, ти тричі відречешся від Мене, і почав плакати."],"x":{"1":"50.26.2|52.22.1","3":"50.26.7|53.11.2|53.12.3","10":"50.26.14|52.22.4","12":"50.26.17|52.22.7","18":"25.40.10|50.26.20|52.22.14|53.13.21","22":"50.26.26|52.22.19|63.11.24","27":"48.13.7|50.26.31|53.16.32","28":"51.16.7","30":"50.26.34|52.22.34|53.13.38","32":"50.26.36|52.22.39","36":"50.26.39|67.2.8|75.5.7-8","38":"52.22.40","43":"50.26.47|52.22.47|53.18.3","49":"24.19.13|25.21.7|25.68.9|25.87.9|31.53.12","53":"50.26.57","55":"25.26.12|25.34.11|50.26.59","58":"51.15.29","61":"31.53.7|54.8.32|75.1.5","62":"50.26.64|70.1.10","66":"50.26.69|52.22.56|53.18.25","72":"50.26.75|51.14.30|50.27.11|52.23.3|53.18.33|71.6.13"}},{"v":["Рано-вранці первосвященики зі старійшинами та книжниками і весь синедріон негайно зібрали раду і, зв’язавши Ісуса, відвели і видали Пилатові.","Пилат спитав Його: Ти Цар Юдейський? Він же сказав йому у відповідь: ти говориш.","І первосвященики звинувачували Його багато в чому.","Пилат же знову спитав Його: Ти нічого не відповідаєш, бачиш, як багато звинувачень проти Тебе?","Але Ісус і на це нічого не відповів, так що Пилат дивувався.","На всяке ж свято він відпускав їм одного в’язня, за якого вони просили.","Тоді був у темниці один на ім’я Варавва, із своїми спільниками, які під час бунту вчинили вбивство.","І народ почав кричати і просити Пилата про те, що він завжди робив для них.","Він сказав їм у відповідь: чи хочете, відпущу вам Царя Юдейського?","Бо знав, що це через заздрість видали Його первосвященики.","Та первосвященики підмовили народ просити, щоб краще відпустив їм Варавву.","Пилат же знову сказав їм у відповідь: що ж хочете, щоб я зробив з Тим, Кого ви називаєте Царем Юдейським?","Вони знову закричали: розіпни Його.","Пилат сказав їм: яке ж зло зробив Він? Вони ж ще дужче закричали: розіпни Його!","Тоді Пилат, бажаючи догодити народові, відпустив їм Варавву, а Ісуса, бивши, віддав на розп’яття.","Воїни відвели Його всередину двору, тобто в преторію, і зібрали весь полк,","і одягли Його в багряницю та, сплівши терновий вінець, поклали на Нього;","і почали вітати Його: радуйся, Царю Юдейський!","І били Його по голові тростиною, і плювали на Нього та, ставши на коліна, кланялися Йому.","Коли ж наглумилися з Нього, зняли з Нього багряницю, одягли Його у власний одяг і повели Його, щоб розіп’яти.","І примусили одного перехожого, який ішов з поля, якогось киринеянина Симона, батька Олександра і Руфа, нести хрест Його.","І привели Його на місце Голгофу, що означає Лобне місце.","І давали Йому пити вино зі смирною; але Він не прийняв.","Ті, що розпинали Його, поділили одяг Його, кидаючи жереб, кому що взяти.","Була третя година, і розіп’яли Його.","І був напис провини Його: Цар Юдейський.","З Ним розіп’яли двох розбійників, одного праворуч, а другого ліворуч Нього.","І збулося Писання, яке говорить: і до злочинців приєднаний.","Ті, що проходили, лихословили на Нього, киваючи головами своїми і кажучи: гей! Ти, Який руйнуєш храм і за три дні створюєш!","Спаси Себе Самого і зійди з хреста.","Так само і первосвященики з книжниками, глузуючи, говорили один одному: інших спасав, а Себе не може спасти!","Христос, Цар Ізраїлів, нехай тепер зійде з хреста, щоб ми бачили, і увіруємо. І розп’яті з Ним ганьбили Його.","О шостій же годині настала темрява по всій землі і тривала до дев’ятої години.","О дев’ятій годині Ісус викрикнув гучним голосом: Елоі! Елоі! Лама савахфані? — що значить: Боже Мій! Боже Мій! Навіщо Ти Мене покинув?","Деякі з тих, що там стояли, почувши те, говорили: Він Іллю кличе.","А один побіг, намочив губку оцтом і, настромивши на тростину, давав Йому пити, кажучи: стривайте, побачимо, чи прийде Ілля зняти Його.","Ісус же, скрикнувши гучним голосом, спустив дух.","І завіса в храмі роздерлася надвоє, зверху донизу.","Сотник, який стояв навпроти Нього, побачивши, як Він, так скрикнувши, віддав дух, сказав: воістину Чоловік Цей був Син Божий.","Були тут і жінки, які дивилися здалеку; між ними були і Марія Магдалина, і Марія, мати Якова молодшого та Іосії, і Саломія,","які і тоді, коли Він був у Галилеї, ходили за Ним і служили Йому, і багато інших, які разом з Ним прийшли до Єрусалима.","І настав уже вечір [бо була п’ятниця, тобто день перед суботою].","Прийшов Йосиф із Аримафеї, поважний радник, який і сам чекав Царства Божого, і насмілився прийти до Пилата просити тіло Ісусове.","Пилат здивувався, що Він уже помер, і, покликавши сотника, спитав його, чи давно помер.","І, довідавшись від сотника, віддав тіло Йосифові.","Він, купивши плащаницю і знявши Його, оповив плащаницею і поклав Його у гробі, витесаному в скелі, і привалив камінь до дверей гробу.","Марія ж Магдалина і Марія Іосієва дивились, де Його поклали."],"x":{"1":"50.27.2|52.22.66","2":"50.27.11|52.23.3|53.18.33|71.6.13","11":"50.27.20|52.23.18|53.18.40|54.3.14","15":"50.27.26|53.19.1","21":"50.27.32|52.23.26","22":"50.27.33|52.23.33|53.19.17|75.13.12","23":"25.68.22","24":"25.21.19|53.19.24","26":"50.27.37","28":"31.53.12","29":"25.68.21|50.26.61|50.27.40|51.14.58|52.22.37|53.2.19","34":"25.21.2|50.27.46","36":"25.68.22|50.27.48","42":"50.27.57","43":"52.23.50|53.19.38","47":"50.27.61"}},{"v":["Як минула субота, Марія Магдалина, Марія Яковова і Саломія купили пахощі, щоб піти помазати Ісуса.","І дуже рано, в перший день після суботи, прийшли до гробу, як сходило сонце.","І говорять між собою: хто відвалить нам камінь від дверей гробу?","І, глянувши, побачили, що камінь відвалений; а він був дуже великий.","І, увійшовши у гріб, побачили юнака, який сидів праворуч і був одягнений у білу одежу; і вжахнулися.","А він каже їм: не жахайтеся. Ісуса шукаєте Назарянина, розп’ятого. Він воскрес — Його нема тут. Ось місце, де поклали Його.","Але йдіть, скажіть ученикам Його і Петрові, що Він буде раніше за вас у Галилеї; там Його побачите, як Він сказав вам.","І, вийшовши, вони побігли від гробу. Охопив їх трепет і жах. І нікому нічого не сказали, бо боялися.","Ісус же, воскреснувши вранці в перший після суботи день, насамперед явився Марії Магдалині, з якої вигнав сім бісів.","Вона пішла і сповістила тих, які були з Ним, що плакали і ридали.","Та вони, почувши, що Він живий і що вона бачила Його, — не повірили.","Після цього явився в іншому образі двом з них на дорозі, коли вони йшли до села.","І ті, повернувшись, сповістили іншим; але й тим не повірили.","Нарешті Він явився самим одинадцятьом, коли вони возлежали на вечері, і дорікав їм за невір’я і жорстокосердість, що не повірили тим, які бачили Його воскреслим.","І сказав їм: ідіть по всьому світу і проповідуйте Євангеліє всьому творінню.","Хто увірує і охреститься, буде спасенний, а хто не увірує, буде осуджений.","Віруючих супроводжуватимуть такі знамення: іменем Моїм виганятимуть бісів; говоритимуть новими мовами,","братимуть змій; і якщо смертоносне щось вип’ють, не пошкодить їм; покладуть руки на недужих, і вони будуть здорові.","Господь же, після розмови з ними, вознісся на небо і сів праворуч Бога.","Вони ж пішли і всюди проповідували, а Господь допомагав їм і стверджував слово наступними знаменнями. Амінь."],"x":{"1":"50.28.1|52.24.1|53.20.1","5":"53.20.12","7":"50.26.32|51.14.28","9":"50.28.9|52.8.2|53.20.14","12":"52.24.13","14":"52.24.36|53.20.19|63.15.5:7","15":"31.2.3|31.52.10|50.28.19|53.15.16","16":"53.12.48","17":"54.2.4|63.12.10","18":"52.10.19|54.28.8|55.5.14","19":"25.109.1|52.24.51|54.1.9","20":"54.14.3|63.3.6|75.2.4"}}];
